// Intake validation (mirrors schemas/procurement-request.schema.json). Weights/scoring overrides pass through untouched.
const b = $input.first().json?.body ?? $input.first().json;
if (!b.requirement || String(b.requirement).length < 5) throw new Error('requirement required (min 5 chars)');
if (!b.currency || !/^[A-Z]{3}$/.test(b.currency)) throw new Error('currency required as ISO 4217');
if (b.quantity != null && !(Number.isInteger(b.quantity) && b.quantity > 0)) throw new Error('quantity must be positive integer');
if (b.budget != null && !(typeof b.budget === 'number' && b.budget > 0)) throw new Error('budget must be positive number');
const __hex = (n) => { let s = ''; for (let i = 0; i < n; i++) s += '0123456789abcdef'[Math.floor(Math.random() * 16)]; return s; };
const __uuid = () => { try { if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID(); } catch (e) {} return __hex(8) + '-' + __hex(4) + '-4' + __hex(3) + '-8' + __hex(3) + '-' + __hex(12); };
const rid = __uuid();
const tid = __uuid();
return [{ json: { procurement_id: rid, trace_id: tid, requirement: b.requirement, quantity: b.quantity ?? null, budget: b.budget ?? null, currency: b.currency, delivery_requirement: b.delivery_requirement ?? null, mandatory_specs: b.mandatory_specs ?? {}, preferred_specs: b.preferred_specs ?? {}, weights: b.weights ?? {}, spec_fields: b.spec_fields ?? ['processor','ram','storage','operating_system','display','battery','graphics'], requested_by: b.requested_by ?? null, auto_close_on_proceed: b.auto_close_on_proceed === true, mode: (b.mode === 'DEMO' ? 'DEMO' : 'REAL'), demo_reason: (b.mode === 'DEMO' ? String(b.demo_reason || '') : null) } }];

// Wrap intake into a state-manager op envelope.
const i = $input.first().json;
return [{ json: { operation: 'create_case', payload: i } }];

// Wrap product output into insert_products op.
const intake = $('Validate Intake').first().json;
const out = $input.first().json;
return [{ json: { operation: 'insert_products', payload: { procurement_id: intake.procurement_id, products: out.products ?? [] } } }];

// Wrap vendor output into insert_offers op (empty offers allowed -> PARTIAL continues).
const intake = $('Validate Intake').first().json;
const out = $('Call Vendor Agent').first().json;
return [{ json: { operation: 'insert_offers', payload: { procurement_id: intake.procurement_id, offers: out.offers ?? [] }, _passthrough_offers: out.offers ?? [] } }];

// Build Review&Quality input from verified products (+ offers if any). No LLM here.
const intake = $('Validate Intake').first().json;
const products = $('Call Product Agent').first().json.products ?? [];
const offers = $('Call Vendor Agent').first().json.offers ?? [];
return [{ json: { procurement_id: intake.procurement_id, trace_id: intake.trace_id, products, offers, spec_fields: intake.spec_fields } }];

// Wrap evaluations into insert op + ensure scoring config exists for comparison.
const intake = $('Validate Intake').first().json;
const out = $input.first().json;
return [{ json: { operation: 'insert_quality_evaluations', payload: { procurement_id: intake.procurement_id, evaluations: out.evaluations ?? [] } } }];

// Upsert scoring config (procurement weights override defaults; never inside LLM prompts).
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'upsert_scoring_config', payload: { procurement_id: intake.procurement_id, weights: intake.weights, spec_fields: intake.spec_fields, notes: 'Phase 2A defaults; override via procurement weights' } } }];

// Mark quality_done (never compared until comparison completes).
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: intake.procurement_id, status: 'quality_done' } } }];

// Build comparison input: products + evaluations + offers + weights. No scoring here.
const intake = $('Validate Intake').first().json;
return [{ json: { procurement_id: intake.procurement_id, trace_id: intake.trace_id, currency: intake.currency, budget: intake.budget, products: $('Call Product Agent').first().json.products ?? [], evaluations: $('Call Review Agent').first().json.evaluations ?? [], offers: $('Call Vendor Agent').first().json.offers ?? [], weights: intake.weights } }];

// Wrap ranked comparisons into insert op.
const intake = $('Validate Intake').first().json;
const out = $input.first().json;
return [{ json: { operation: 'insert_comparisons', payload: { procurement_id: intake.procurement_id, comparisons: out.comparisons ?? [] } } }];

// Mark compared ONLY after deterministic comparison persisted.
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: intake.procurement_id, status: 'compared' } } }];

// Build decision input: ranked comparisons + products + offers + procurement constraints. No scoring here.
const intake = $('Validate Intake').first().json;
const conv = (specs) => { const m = {}; for (const [k, v] of Object.entries(intake.mandatory_specs ?? {})) { const s = String(k); if (s.endsWith('_min')) m[s.slice(0, -4)] = { min: v }; else if (s.endsWith('_max')) m[s.slice(0, -4)] = { ...(m[s.slice(0, -4)] || {}), max: v }; else m[s] = { equals: v }; } return m; };
return [{ json: { procurement_id: intake.procurement_id, trace_id: intake.trace_id, procurement: { procurement_id: intake.procurement_id, currency: intake.currency, budget: intake.budget, quantity: intake.quantity }, ranked: $('Call Comparison').first().json.comparisons ?? [], offersByProduct: {}, vendorsById: {}, productsById: Object.fromEntries(($('Call Product Agent').first().json.products ?? []).map((p) => [p.product_id, p])), mandatory: conv() } }];

// Wrap decision into insert_decisions op.
const intake = $('Validate Intake').first().json;
const d = $input.first().json;
return [{ json: { operation: 'insert_decisions', payload: { procurement_id: intake.procurement_id, decisions: [d] } } }];

// Mark decided. State changes stop here for non-negotiated outcomes.
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: intake.procurement_id, status: 'decided' } } }];

// Build negotiation input from the decision's verified offer (+ vendor/product lookups). Empty vendor/offer -> agent returns NOT_READY.
const intake = $('Validate Intake').first().json;
const d = $('Call Decision').first().json;
const offers = $('Call Vendor Agent').first().json.offers ?? [];
const off = (d._offer && offers.find((o) => o.offer_id === d._offer.offer_id)) || null;
return [{ json: { procurement_id: intake.procurement_id, trace_id: intake.trace_id, decision: d, vendor: null, offer: off, product: null, procurement: { currency: intake.currency, budget: intake.budget, quantity: intake.quantity }, allowed_discount_pct: null, requested_terms: [] } }];

// Wrap: eligible -> insert_negotiations + human_review_required event; NOT_READY -> evaluated_not_ready event only (no fake rows).
const intake = $('Validate Intake').first().json;
const r = $input.first().json;
if (r.status === 'NOT_READY') return [{ json: { operation: 'insert_negotiation_events', payload: { procurement_id: intake.procurement_id, trace_id: intake.trace_id, events: [{ offer_id: null, event_type: 'evaluated_not_ready', metadata: { reasons: r.reasons } }] } } }];
return [{ json: { operation: 'insert_negotiations', payload: { procurement_id: intake.procurement_id, negotiations: [{ ...r.negotiation, message: r.message }] } } }];

// Mark negotiating (real negotiation row exists).
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: intake.procurement_id, status: 'negotiating' } } }];

// Wrap snapshot read for the reevaluation path.
const body = ($input.first().json?.body ?? $input.first().json);
return [{ json: { operation: 'fetch_snapshot', payload: { procurement_id: body.procurement_id }, _vendor_response: body.vendor_response ?? null, _trace_id: body.trace_id ?? null } }];

// Shape reevaluation input from snapshot + real response. Components rebuilt from persisted breakdown scores.
const snap = $input.first().json.snapshot ?? $input.first().json;
const prev = $('Op Fetch Reeval Snapshot').first().json;
const body_response = prev._vendor_response;
const nego = (snap.negotiations || []).find((n) => n.negotiation_id === (body_response && body_response.negotiation_id)) || (snap.negotiations || [])[0] || null;
if (!nego) return [{ json: { procurement_id: snap.procurement.procurement_id, negotiation: null, vendor_response: null } }];
const comp0 = (snap.comparisons || []).find((c) => c.product_id === nego.product_id) || {};
const bd0 = comp0.criteria_scores || {};
const compMap = Object.fromEntries(Object.entries(bd0).map(([k, v]) => [k, (v && typeof v.score === 'number') ? v.score : null]));
const offer0 = (snap.offers || []).find((o) => o.offer_id === nego.offer_id) || null;
return [{ json: { procurement_id: snap.procurement.procurement_id, trace_id: prev._trace_id, negotiation: nego, offer: offer0, vendor: (snap.vendors || []).find((v) => v.vendor_id === nego.vendor_id) || null, product: (snap.products || []).find((p) => p.product_id === nego.product_id) || null, vendor_response: body_response, original: { components: compMap, price: (offer0 && offer0.net_price) || nego.current_price || null, currency: (offer0 && offer0.currency) || nego.currency || null, budget: (snap.procurement && snap.procurement.budget) || null }, weights: {} } }];

// Wrap reevaluation into insert op.
const out = $input.first().json;
return [{ json: { operation: 'insert_reevaluations', payload: { procurement_id: out.procurement_id, reevaluations: [out] } } }];

// Mark reevaluated ONLY after verified recomputation persisted.
const out = $('Call Reevaluation').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: out.procurement_id, status: 'reevaluated' } } }];

// Minimal approval base from either path (post-negotiation or PROCEED-direct). Snapshot loaded next.
const src = $('Mark Reevaluated').first().json?.procurement_id ? $('Call Reevaluation').first().json : $('Call Decision').first().json;
const intake = $('Validate Intake').first().json;
return [{ json: { procurement_id: src.procurement_id ?? intake.procurement_id, trace_id: intake.trace_id } }];

// Wrap snapshot read.
const i = $input.first().json;
return [{ json: { operation: 'fetch_snapshot', payload: { procurement_id: i.procurement_id } } }];

// Shape full approval input from the authoritative snapshot. Gaps stay unavailable.
const snap = $input.first().json.snapshot ?? $input.first().json;
const dec = snap.decision || {};
const ranked = snap.comparisons || [];
const top = ranked[0] || {};
const offers = snap.offers || [];
const best = offers.find((o) => o.offer_id === (dec._offer?.offer_id ?? dec.product_id)) || offers[0] || null;
const re = (snap.reevaluations || [])[0] || null;
const nego = (snap.negotiations || [])[0] || null;
const prod = (snap.products || []).find((p) => p.product_id === (dec.product_id || top.product_id)) || null;
return [{ json: { procurement_id: snap.procurement.procurement_id, trace_id: $('Build Approval Base').first().json.trace_id, snapshot: snap.procurement, selected_product: prod ?? 'unavailable', selected_vendor: ((snap.vendors || []).find((v) => v.vendor_id === (best?.vendor_id || nego?.vendor_id)) ?? 'unavailable'), original_offer: best ?? 'unavailable', revised_offer: re ? { revised_price: re.revised_price, currency: re.currency, absolute_savings: re.absolute_savings, percentage_savings: re.percentage_savings } : 'unavailable', original_score: top.overall_score ?? 'unavailable', revised_score: re ? re.revised_score : 'unavailable', savings: re ? { absolute: re.absolute_savings, percentage: re.percentage_savings, currency: re.currency } : 'unavailable', quality_evidence: 'unavailable', review_evidence: 'unavailable', delivery_information: best?.delivery_days ?? 'unavailable', warranty_information: best?.warranty_months ?? 'unavailable', payment_terms: best?.payment_terms ?? 'unavailable', criteria_used: top.criteria_used ?? [], criteria_missing: top.criteria_missing ?? [], limitations: (top.limitations ?? []).concat(dec.decision ? ['Decision: ' + dec.decision + ' — ' + (dec.decision_reason ?? '')] : []), evidence_urls: top.evidence_urls ?? [], negotiation_history: snap.negotiations || [], expires_at: null } }];

// Record the human outcome: returns the update_approval envelope and carries the outcome event envelope + outcome for downstream nodes.
const intake = $('Validate Intake').first().json;
const o = $('Call Approval (waits for human)').first().json;
const ev = o.outcome === 'APPROVED' ? 'approval_approved' : o.outcome === 'REJECTED' ? 'approval_rejected' : 'approval_changes_requested';
return [{ json: { operation: 'update_approval', payload: { procurement_id: intake.procurement_id, decision: o.outcome, approved_by: o.approved_by, approved_at: o.approved_at, decision_reason: o.decision_reason ?? null }, _event: { operation: 'insert_approval_events', payload: { procurement_id: intake.procurement_id, trace_id: intake.trace_id, events: [{ event_type: ev, actor: o.approved_by, metadata: { outcome: o.outcome } }] } } } }];

// Pass through the carried outcome-event envelope.
const w = $('Op Record Approval').first().json;
return [{ json: w._event }];

// Mark closed ONLY on explicit APPROVED/REJECTED.
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: intake.procurement_id, status: 'closed' } } }];

// CHANGES_REQUESTED never closes.
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: intake.procurement_id, status: 'changes_requested' } } }];

// Legitimate early closure: PROCEED + explicit rule. No approval required by rule; rule recorded in audit metadata downstream.
const intake = $('Validate Intake').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: intake.procurement_id, status: 'closed' } } }];

// Create the PENDING approval row (mode-aware) from the shaped input. No decision here.
const s = $input.first().json;
const pid = (o) => (o && typeof o === 'object' ? (o.product_id ?? o.vendor_id ?? o.offer_id ?? null) : null);
return [{ json: { operation: 'insert_approvals', payload: { procurement_id: s.procurement_id, approvals: [{ selected_product_id: pid(s.selected_product), selected_vendor_id: (s.selected_vendor && s.selected_vendor.vendor_id) || null, selected_offer_id: (s.original_offer && s.original_offer.offer_id) || null, mode: (s.snapshot && s.snapshot.procurement && s.snapshot.procurement.mode) || 'REAL', status: 'PENDING_APPROVAL', approval_package: s }] } } }];

// Record approval_created (system actor — not a human decision).
const intake = $('Validate Intake').first().json;
const pid = $('Build Approval Base').first().json.procurement_id;
return [{ json: { operation: 'insert_approval_events', payload: { procurement_id: pid, trace_id: intake.trace_id, events: [{ event_type: 'approval_created', actor: 'system', metadata: { mode: 'see-approvals-table' } }] } } }];

// Wrap snapshot read for the demo path (carries the explicit DEMO request).
const body = ($input.first().json?.body ?? $input.first().json);
return [{ json: { operation: 'fetch_snapshot', payload: { procurement_id: body.procurement_id }, _demo: { offer_id: body.offer_id ?? null, mode: body.mode ?? null, reason: body.reason ?? null, target_price: body.target_price ?? null } } }];

// Build an explicitly-DEMO negotiation from REAL offer/vendor/product rows. Mode switch requires reason.
const snap = $input.first().json.snapshot ?? $input.first().json;
const req = $('Op Fetch Demo Snapshot').first().json._demo || {};
if (req.mode !== 'DEMO') throw new Error('demo path requires explicit mode=DEMO (never silent)');
if (!req.reason || !String(req.reason).trim()) throw new Error('explicit DEMO selection requires a reason');
if (!req.offer_id) throw new Error('demo negotiation requires a real offer_id');
const offer = (snap.offers || []).find((o) => o.offer_id === req.offer_id);
if (!offer || !(typeof offer.net_price === 'number') || !offer.currency) throw new Error('demo requires a real verified offer (price+currency)');
const vendor = (snap.vendors || []).find((v) => v.vendor_id === offer.vendor_id);
if (!vendor || !vendor.vendor_name || vendor.vendor_name === 'unavailable') throw new Error('demo requires a real vendor');
const product = (snap.products || []).find((p) => p.product_id === offer.product_id) || null;
const unitBudget = snap.procurement?.budget && snap.procurement?.quantity ? snap.procurement.budget / snap.procurement.quantity : null;
const target = (typeof req.target_price === 'number' && req.target_price > 0) ? req.target_price : (unitBudget !== null && unitBudget < offer.net_price ? unitBudget : null);
const dtrace = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : ('demo-' + Date.now());
return [{ json: { procurement_id: snap.procurement.procurement_id, trace_id: dtrace, mode: 'DEMO', reason: req.reason, offer, vendor, product, target_price: target, status: 'DEMO_READY_FOR_RESPONSE' } }];

// Switch case to DEMO (explicit + reasoned). REAL cases never pass here.
const d = $input.first().json;
return [{ json: { operation: 'set_case_mode', payload: { procurement_id: d.procurement_id, mode: 'DEMO', reason: d.reason } } }];

// Persist the DEMO negotiation (real FKs, DEMO labels, never sent).
const d = $('Build Demo Negotiation').first().json;
const o = d.offer;
const discount = d.target_price !== null ? Math.round((1 - d.target_price / o.net_price) * 10000) / 100 : null;
return [{ json: { operation: 'insert_negotiations', payload: { procurement_id: d.procurement_id, negotiations: [{ product_id: o.product_id, vendor_id: o.vendor_id, offer_id: o.offer_id, mode: 'DEMO', status: 'DEMO_READY_FOR_RESPONSE', current_price: o.net_price, currency: o.currency, target_price: d.target_price, requested_discount_percent: discount, requested_terms: [], contact_channel: { type: 'other', address: 'LOCAL_DEMO_ONLY', source_url: o.source_url, status: 'LIVE' }, human_confirmation: false, do_not_send: true }] } } }];

// Record demo_mode_selected + demo_negotiation_created (system actor).
const d = $('Build Demo Negotiation').first().json;
const intake = { trace_id: d.trace_id };
return [{ json: { operation: 'insert_negotiation_events', payload: { procurement_id: d.procurement_id, trace_id: d.trace_id, events: [{ offer_id: d.offer.offer_id, event_type: 'demo_mode_selected', metadata: { mode: 'DEMO', reason: d.reason, actor: 'HUMAN' } }, { offer_id: d.offer.offer_id, event_type: 'demo_negotiation_created', metadata: { mode: 'DEMO', no_message_sent: true, actor: 'HUMAN' } }] } } }];

// Mark demo_negotiating (never negotiating: no real channel).
const d = $('Build Demo Negotiation').first().json;
return [{ json: { operation: 'update_status', payload: { procurement_id: d.procurement_id, status: 'demo_negotiating' } } }];

// Shape Product Agent input from the validated intake (pg result carries no requirement data).
const i = $('Validate Intake').first().json;
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, requirement: i.requirement, quantity: i.quantity, budget: i.budget, currency: i.currency, delivery_requirement: i.delivery_requirement, mandatory_specs: i.mandatory_specs, preferred_specs: i.preferred_specs } }];

// Shape Vendor Agent input: verified products + case currency (pg result carries neither).
const intake = $('Validate Intake').first().json;
const products = $('Call Product Agent').first().json.products ?? [];
return [{ json: { procurement_id: intake.procurement_id, trace_id: intake.trace_id, currency: intake.currency, products } }];

const intake = $('Validate Intake').first().json;
const vendors = $('Call Vendor Agent').first().json.vendors ?? [];
return [{ json: { operation: 'insert_vendors', payload: { procurement_id: intake.procurement_id, vendors } } }];
